<template><div class="page"><header><div><h2>Banco y Conciliación</h2><p>Cheques, transferencias y conciliaciones bancarias mensuales.</p></div><label>Finca<select v-model="fincaId" @change="cargar"><option value="">Seleccione</option><option v-for="f in fincas" :key="f.id" :value="f.id">{{f.code}} - {{f.name}}</option></select></label></header><section class="card"><h3>Cheque o transferencia</h3><form @submit.prevent="guardarMovimiento"><label>Tipo<select v-model="mov.tipo"><option value="CHEQUE">Cheque</option><option value="TRANSFERENCIA">Transferencia</option></select></label><label>Fecha emisión<input v-model="mov.fechaEmision" type="date" /></label><label>Beneficiario<input v-model.trim="mov.beneficiario" required /></label><label>Importe<input v-model.number="mov.importe" type="number" min=".01" step=".01" /></label><label>Autorizado por<input v-model.trim="mov.autorizadoPor" required /></label><label>Emitido por<input v-model.trim="mov.emitidoPor" required /></label><label class="wide">Concepto<input v-model.trim="mov.concepto" required /></label><div class="actions"><button class="primary" :disabled="!fincaId">Registrar</button></div></form><div class="wrap"><table><thead><tr><th>Tipo</th><th>Ref.</th><th>Fecha</th><th>Beneficiario</th><th>Importe</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="m in cheques" :key="m.id"><td>{{m.tipo}}</td><td>{{m.numero||m.referenciaBancaria||'—'}}</td><td>{{fecha(m.fecha)}}</td><td>{{m.beneficiario}}</td><td class="money">{{moneda(m.importe)}}</td><td>{{m.estado}}</td><td><button v-if="m.estado==='EMITIDO'" class="link" @click="confirmar(m)">Confirmar cobro</button></td></tr></tbody></table></div></section><section class="card"><h3>Conciliación mensual</h3><form @submit.prevent="guardarConciliacion"><label>Período<input v-model="conc.periodo" type="month" /></label><label>Saldo extracto<input v-model.number="conc.saldoExtracto" type="number" step=".01" /></label><label>Saldo libros<input v-model.number="conc.saldoLibros" type="number" step=".01" /></label><label>Responsable<input v-model.trim="conc.responsable" required /></label><label class="wide">Observaciones<input v-model.trim="conc.observaciones" /></label><div class="actions"><button class="primary" :disabled="!fincaId">Crear conciliación</button></div></form><div v-if="detalle" class="detail"><h4>Detalle {{detalle.periodo}}</h4><button v-if="detalle.estado!=='CERRADA'" class="primary" @click="cerrar">Cerrar conciliación</button><table><thead><tr><th>Fecha</th><th>Origen</th><th>Descripción</th><th>Referencia</th><th>Importe</th><th>Conciliado</th></tr></thead><tbody><tr v-for="m in detalle.movimientos||[]" :key="m.id"><td>{{fecha(m.fecha)}}</td><td>{{m.origen||'—'}}</td><td>{{m.descripcion}}</td><td>{{m.referencia||'—'}}</td><td class="money">{{moneda(m.importe)}}</td><td>{{m.conciliado?'Sí':'No'}}</td></tr></tbody></table></div><div class="wrap"><table><thead><tr><th>Período</th><th>Responsable</th><th>Extracto</th><th>Libros</th><th>Diferencia</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="c in conciliaciones" :key="c.id"><td>{{c.periodo}}</td><td>{{c.responsable}}</td><td class="money">{{moneda(c.saldoExtracto)}}</td><td class="money">{{moneda(c.saldoLibros)}}</td><td class="money">{{moneda(c.diferencia)}}</td><td>{{c.estado}}</td><td><button class="link" @click="ver(c.id)">Detalle</button></td></tr></tbody></table></div></section></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{notify}from'@/composables/useNotification';import FincaService from'@/services/FincaService';import S,{type ChequeTransferencia,type ChequeTransferenciaRequest,type ConciliacionBancaria,type ConciliacionRequest}from'@/services/BancoDocumentosCajaService';const d=new Date(),fincaId=ref(''),fincas=ref<Array<{id:string;code:string;name:string}>>([]),cheques=ref<ChequeTransferencia[]>([]),conciliaciones=ref<ConciliacionBancaria[]>([]),detalle=ref<ConciliacionBancaria|null>(null),mov=reactive({tipo:'CHEQUE' as 'CHEQUE'|'TRANSFERENCIA',fechaEmision:d.toISOString().slice(0,10),beneficiario:'',concepto:'',importe:0,referenciaBancaria:'',autorizadoPor:'',emitidoPor:''}),conc=reactive({periodo:d.toISOString().slice(0,7),saldoExtracto:0,saldoLibros:0,responsable:'',observaciones:''});const moneda=(x:number)=>`$${(x||0).toLocaleString('es-CU',{minimumFractionDigits:2,maximumFractionDigits:2})}`,fecha=(x?:string)=>x?new Date(x).toLocaleDateString('es-CU'):'—';async function cargar(){if(!fincaId.value)return;try{const[a,b]=await Promise.all([S.listarCheques(fincaId.value),S.listarConciliaciones(fincaId.value)]);cheques.value=a.data||[];conciliaciones.value=b.data||[]}catch(e){console.error(e);notify.error('Error','No se pudo cargar banco.')}}async function guardarMovimiento(){if(!fincaId.value||!mov.beneficiario||!mov.concepto||!mov.autorizadoPor||!mov.emitidoPor||mov.importe<=0)return;try{const r:ChequeTransferenciaRequest={...mov,fincaId:fincaId.value,fechaEmision:`${mov.fechaEmision}T00:00:00`,referenciaBancaria:mov.referenciaBancaria||undefined};await S.crearCheque(r);await cargar();notify.success('Movimiento emitido','Quedó pendiente de cobro.')}catch(e){console.error(e);notify.error('Error','No se pudo emitir el movimiento.')}}async function confirmar(m:ChequeTransferencia){const o=window.prompt('Observaciones de confirmación:');if(o===null)return;try{await S.confirmarCheque(m.id,true,o||undefined);await cargar();notify.success('Confirmado','Movimiento marcado como cobrado.')}catch(e){console.error(e);notify.error('Error','No se pudo confirmar.')}}async function guardarConciliacion(){if(!fincaId.value||!conc.responsable)return;try{const r:ConciliacionRequest={fincaId:fincaId.value,periodo:`${conc.periodo}-01`,saldoExtracto:conc.saldoExtracto,saldoLibros:conc.saldoLibros,responsable:conc.responsable,observaciones:conc.observaciones||undefined,movimientos:[]};const x=await S.crearConciliacion(r);await cargar();await ver(x.data.id);notify.success('Conciliación creada','Puede revisar y cerrar el detalle.')}catch(e){console.error(e);notify.error('Error','No se pudo crear conciliación.')}}async function ver(id:string){try{detalle.value=(await S.obtenerConciliacion(id)).data}catch(e){console.error(e);notify.error('Error','No se pudo cargar detalle.')}}async function cerrar(){if(!detalle.value)return;const o=window.prompt('Observaciones de cierre:');if(o===null)return;try{await S.cerrarConciliacion(detalle.value.id,o||undefined);await ver(detalle.value.id);await cargar();notify.success('Conciliación cerrada','Cierre registrado.')}catch(e){console.error(e);notify.error('Error','No se pudo cerrar.')}}onMounted(async()=>{try{fincas.value=(await FincaService.buscarFincas({size:999})).data.data||[]}catch(e){console.error(e)}})</script>
<style scoped>.page{max-width:1400px;margin:auto;padding:1.5rem}header{display:flex;justify-content:space-between}h2,h3{color:#1e3a5f}.card{border:1px solid #dbe4ea;border-radius:10px;padding:1.25rem;margin:1rem 0}form{display:grid;grid-template-columns:repeat(4,1fr);gap:.7rem}label{display:grid;font-size:.8rem;gap:.2rem}input,select{padding:.5rem;border:1px solid #cbd5e1;border-radius:5px}.wide{grid-column:span 2}.actions{display:flex;align-items:end}.primary,.link{border:0;border-radius:6px;padding:.6rem;cursor:pointer}.primary{background:#2563eb;color:#fff}.link{background:none;color:#2563eb}.wrap{overflow:auto;margin-top:1rem}table{width:100%;min-width:750px;border-collapse:collapse}th,td{padding:.55rem;border-bottom:1px solid #e2e8f0;text-align:left}.money{text-align:right}@media(max-width:800px){header{flex-direction:column}form{grid-template-columns:1fr}.wide{grid-column:span 1}}</style>
